[{"order":1,"type":"heading","text":"Exception Handling Extensions in JUnit 5: TestExecutionExceptionHandler"},{"order":2,"type":"paragraph","text":"JUnit 5 provides a powerful extension model that allows developers to customize test lifecycle execution. One of the most useful extensions for robust error management is the TestExecutionExceptionHandler interface, which enables you to intercept and handle exceptions thrown during test execution."},{"order":3,"type":"subheading","text":"Understanding TestExecutionExceptionHandler"},{"order":4,"type":"paragraph","text":"The TestExecutionExceptionHandler interface defines a single method: handleTestExecutionException(ExtensionContext context, Throwable throwable). By implementing this interface, your extension can decide whether to rethrow the caught exception, suppress it, or handle it in a custom manner such as logging or taking screenshots in UI tests."},{"order":5,"type":"subheading","text":"Implementing a Custom Exception Handler"},{"order":6,"type":"paragraph","text":"Below is an example of a custom exception handler that suppresses a specific type of exception, allowing the test run to proceed or fail gracefully based on your custom business logic."},{"order":7,"type":"code","text":"import org.junit.jupiter.api.extension.ExtensionContext;
import org.junit.jupiter.api.extension.TestExecutionExceptionHandler;

public class SwallowCustomExceptionExtension implements TestExecutionExceptionHandler {
    @Override
    public void handleTestExecutionException(ExtensionContext context, Throwable throwable) throws Throwable {
        if (throwable instanceof IllegalArgumentException) {
            // Suppress the exception by doing nothing
            return;
        }
        // Rethrow any other exception so JUnit marks the test as failed
        throw throwable;
    }
}"},{"order":8,"type":"subheading","text":"Applying the Extension to Tests"},{"order":9,"type":"paragraph","text":"To use your custom handler, you can register it declaratively using the @ExtendWith annotation on your test class or test method."},{"order":10,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;

@ExtendWith(SwallowCustomExceptionExtension.class)
public class ExceptionHandlerTest {

    @Test
    void testThatThrowsIgnoredException() {
        throw new IllegalArgumentException("This will be swallowed by the extension.");
    }
}"},{"order":11,"type":"subheading","text":"Best Practices"},{"order":12,"type":"bullet_point","text":"Always rethrow exceptions you do not explicitly know how to handle, otherwise unexpected failures might go unnoticed."},{"order":13,"type":"bullet_point","text":"Combine TestExecutionExceptionHandler with LifeCycleCallbacks to perform clean-up actions when exceptions occur."},{"order":14,"type":"bullet_point","text":"Keep handlers focused on cross-cutting concerns like logging, reporting, or specific error-recovery patterns."}]
